const src = $json || {};
const exec = src.execution || {};
const wf = src.workflow || {};

function safeString(v) {
    if (v === null || v === undefined) return null;
    if (typeof v === 'string') return v.trim() || null;
    if (typeof v !== 'object') return String(v);
    const seen = new WeakSet();
    let out = null;
    try {
          out = JSON.stringify(v, (k, val) => {
                  if (typeof val === 'object' && val !== null) {
                            if (seen.has(val)) return '[circulaire]';
                            seen.add(val);
                  }
                  return val;
          });
    } catch (e) {
          out = null;
    }
    if (out && out !== '{}' && out !== 'null') return out;_
    const parts = [];
    for (const k of Object.keys(v)) {
          const val = v[k];
          if (val === null || val === undefined) continue;
          if (typeof val === 'object') continue;
          parts.push(k + '=' + String(val));
    }
    return parts.length ? parts.join(' | ') : null;
}

const err = exec.error || src.error || null;

let nodeName =
    (err && err.node && err.node.name) ||
    (err && typeof err.node === 'string' ? err.node : null) ||
    (src.node && src.node.name) ||
    exec.lastNodeExecuted ||
    src.lastNodeExecuted ||
    null;

let message = null;
if (err) {
    message =
          safeString(err.message) ||
          safeString(err.description) ||
          safeString(err.reason) ||
          safeString(err.stack) ||
          safeString(err);
}
if (!message) {
    message = safeString(src.message) || safeString(src);
}

const mode = exec.mode || src.mode || null;
const execId = exec.id || src.id || null;
const contexte = [];
if (execId) contexte.push('execution ' + execId);
if (mode) contexte.push('mode ' + mode);
if (contexte.length) {
    message = (message || 'Erreur sans message') + ' (' + contexte.join(', ') + ')';
}

return [{
    json: {
          garage_id: 'bcd7f692-1c28-435c-87d1-92f84aa0e6bb',
          workflow_nom: wf.name || 'Nexora - Assistant Garage Avancé',
          noeud: nodeName || 'Inconnu',
          message: message || 'Erreur inconnue',
    }
}];
